window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"6sJZwNwB5vU","speaker":"Michaël Randrianirina","role":"President","country":"Madagascar","region":"Africa","url":"https://www.youtube.com/watch?v=6sJZwNwB5vU","date":"20260924","title":"🇲🇬 Madagascar - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1292,"words":2173,"counts":{"claims":31,"promises":3,"attacks":0},"topics":[{"topic":"UN reform","share":0.3204,"seconds":414},{"topic":"Madagascar development","share":0.1051,"seconds":136},{"topic":"Madagascar neutrality","share":0.1027,"seconds":133},{"topic":"Madagascar climate","share":0.067,"seconds":87},{"topic":"financial reform","share":0.0618,"seconds":80},{"topic":"Regional cooperation","share":0.0555,"seconds":72},{"topic":"UNGA 81st session","share":0.0531,"seconds":69},{"topic":"Madagascar elections","share":0.0502,"seconds":65},{"topic":"Africa","share":0.049,"seconds":63},{"topic":"Climate finance","share":0.0482,"seconds":62},{"topic":"Madagascar education","share":0.0481,"seconds":62},{"topic":"Ceremony","share":0.0389,"seconds":50}],"timeline":[[3,81,null],[83,152,"UNGA 81st session"],[153,216,"Madagascar development"],[218,281,"UN reform"],[282,368,"Madagascar climate"],[376,448,"Madagascar development"],[449,511,"Madagascar education"],[512,577,"Madagascar neutrality"],[578,651,"UN reform"],[655,722,"Madagascar neutrality"],[724,796,"Regional cooperation"],[797,873,"UN reform"],[876,948,"UN reform"],[949,1013,"UN reform"],[1013,1076,"Africa"],[1078,1157,"financial reform"],[1159,1221,"Climate finance"],[1223,1289,"UN reform"],[1291,1356,"Madagascar elections"],[1360,1410,"Ceremony"]],"stances":{"UNGA 81st session":"Michaël Randrianirina congratulates the newly elected president of the 81st General Assembly and reaffirms Madagascar's support for the session's success.","Madagascar development":"Michaël Randrianirina states that existing challenges like food insecurity and conflict remain urgent for Madagascar alongside new emerging issues.","UN reform":"Michaël Randrianirina states that trust in the United Nations has gradually eroded over time due to ongoing global challenges.","Madagascar climate":"Michaël Randrianirina describes the severe impact of climate change on Madagascar's population and highlights the role of development partners in addressing these issues.","Madagascar education":"The speaker advocates for aligning the education system with labor market realities and prioritizing practical skills over quantitative metrics.","Madagascar neutrality":"Michaël Randrianirina states that Madagascar maintains a policy of neutrality in global conflicts based on its diplomatic tradition and desire for constructive relations with all partners.","Regional cooperation":"The speaker expresses determination to strengthen regional and multilateral cooperation based on sovereignty and partnerships that drive development.","Africa":"Michaël Randrianirina advocates for Africa to receive permanent representation on the Security Council based on the Ezulwini consensus and calls for UN programs to align with national priorities.","financial reform":"Michaël Randrianirina argues that the international financial architecture must be reformed to better support vulnerable countries by incorporating multi-dimensional vulnerability indices and improving debt restructuring mechanisms.","Climate finance":"The speaker argues that UN fund access procedures must be simplified to reduce delays and that the multilateral system should ensure developed nations honor their climate finance commitments.","Madagascar elections":"The speaker states that Madagascar has launched an inclusive national dialogue and set a timetable to hold free, transparent, and universally accepted elections before the end of 2027.","Ceremony":"The speaker expresses gratitude to partners and the SADC community for their support during Madagascar's refoundation process."},"claims":[{"t":83,"quote":"at this 81st session of the United Nations General Assembly for the rest of my speech. Allow me to now speak to you in the Malagasi language, my mother tongue, in honor of my country and the Malagasi I would like first of all on behalf of the Malagasi people and in my own name to extend my sincere congratulations to Mr. Khalur Rakman on his election as president of the 81st general assembly as well as to the vice In this regard, I wish to reaffirm Madagascar's support and its full readiness to work in a genuine spirit of cooperation to ensure the success of all of our work throughout this session.","topic":"UNGA 81st session","kind":"fact"},{"t":159,"quote":"the challenges that we have faced for decades, namely food insecurity, armed conflict, or natural disasters are still with us","topic":"Madagascar development","kind":"fact"},{"t":245,"quote":"trust has gradually eroded over time","topic":"UN reform","kind":"fact"},{"t":250,"quote":"The most vulnerable populations affected repeatedly or continuously by health crisis, food insecurity and hunger","topic":"UN reform","kind":"fact"},{"t":292,"quote":"In southern Madagascar, mothers walk dozens of kilometers under scorching heat in search of water from the bed of a dried up river.","topic":"Madagascar climate","kind":"fact"},{"t":309,"quote":"In the east, every year, increasingly violent and destructive tropical cyclones devastate crops, infrastructure, and human lives.","topic":"Madagascar climate","kind":"fact"},{"t":321,"quote":"In other regions, floods engulf rice granaries affecting entire communities.","topic":"Madagascar climate","kind":"fact"},{"t":376,"quote":"And we hope to mobilize $1.5 billion over 5 years for the implementation of the United Nations Sustainable Development Cooperation Framework for the period 2024 2028.","topic":"Madagascar development","kind":"number"},{"t":430,"quote":"With more than 55% of its population under the age of 25, enjoys a tremendous demographic Driven by a firm political determination to build a brighter future for this dynamic youth.","topic":"Madagascar development","kind":"number"},{"t":449,"quote":"We recognize the importance of an education system which is fully aligned with labor market realities, an essential condition for sustainable development.","topic":"Madagascar education","kind":"fact"},{"t":473,"quote":"Our aim is to focus on future oriented sectors while redefining our indicators of success to prioritize the practical acquisition of skills and medium-term employment outcomes.","topic":"Madagascar education","kind":"self_credit"},{"t":512,"quote":"Madagascar has chosen a policy of engagement in all We are open to all international partnerships capable of meeting the aspirations of our people and supporting the general policy of the state of the Madagascar's position of neutrality with regard to global conflicts is consistent with its diplomatic tradition and its desire to preserve constructive relations with all its partners. is not ideological but is based on international partnership that can meet the aspirations of our people in an open spirit without exclusivity in full respect for ational sovereignty.","topic":"Madagascar neutrality","kind":"fact"},{"t":578,"quote":"The achievement of our ambitions cannot be separated from the international context in which they are pursued.","topic":"UN reform","kind":"fact"},{"t":616,"quote":"We must be concerned that the multilateral system is struggling to contain escalating tensions fueled by geopolitical rivalries.","topic":"UN reform","kind":"fact"},{"t":710,"quote":"Maritime security in the Mosambique channel and the western Indian Ocean remains at the heart of the regional initiatives in which Madagascar act actively participates.","topic":"Madagascar neutrality","kind":"fact"},{"t":724,"quote":"We are determined to strengthen regional and multilateral cooperation founded on respect for national sovereignty.","topic":"Regional cooperation","kind":"fact"},{"t":757,"quote":"This approach will make it possible to ensure the sustainability of our energy supply chains.","topic":"Regional cooperation","kind":"fact"},{"t":807,"quote":"better Madagascar advocates for a multilateral that is not only capable of acting, but that is also capable of supporting member states in their efforts to break the cycles of poverty and insecurity.","topic":"UN reform","kind":"fact"},{"t":828,"quote":"My country aspires to an international order founded on the primacy of international law and trusts in the virtues of dialogue and diplomatic action.","topic":"UN reform","kind":"fact"},{"t":876,"quote":"History and future generations will judge our organization according to a single criterion, namely our ability to fulfill our original mission. serving all peoples without exclusion or privilege and in full respect for the sovereignty of nations.","topic":"UN reform","kind":"fact"},{"t":937,"quote":"the success of our agenda largely depends on strengthening governance and strengthening institutions priorities that are fully integrated into Madagascar's process of reoundation.","topic":"UN reform","kind":"fact"},{"t":981,"quote":"It remains indeed the only organ where every nation regardless of power enjoys an equal and sovereign","topic":"UN reform","kind":"fact"},{"t":1013,"quote":"We have 1.4 billion inhabitants, decisions concerning international peace and security.","topic":"Africa","kind":"number"},{"t":1022,"quote":"Africa should be granted permanent representation on the security council in accordance with the Ezelwini consensus and the cert declaration which expresses which express a common position grounded in justice equity and represent representativeness within the African Union.","topic":"Africa","kind":"fact"},{"t":1090,"quote":"Current aid and lending criteria often rely solely on GDP per capita, excluding many vulnerable countries.","topic":"financial reform","kind":"fact"},{"t":1101,"quote":"The United Nations should therefore take into account the multi-dimensional vulnerability index so that access to concessional financing reflects climate shocks and external debt burdens.","topic":"financial reform","kind":"fact"},{"t":1168,"quote":"For a vulnerable state facing crisis, slowness undermines confidence in the effectiveness of multilateralism.","topic":"Climate finance","kind":"fact"},{"t":1247,"quote":"Building upon the achievements of the United Nations over 81 years.","topic":"UN reform","kind":"fact"},{"t":1259,"quote":"Our predecessors were able to build an organization suited to their time.","topic":"UN reform","kind":"fact"},{"t":1292,"quote":"the process of refoundation initiated following the mobilization of Malagasi youth just one year ago serves as the foundation for responsible governance supported by strong institutions devoted to the public interest and having restored citizens trust in the state.","topic":"Madagascar elections","kind":"fact"},{"t":1327,"quote":"we have launched a historic process of inclusive national dialogue, bringing together all the vital forces of the nation, young people, women, persons with disabilities, political parties, civil society, the armed forces, and the private sector.","topic":"Madagascar elections","kind":"fact"}],"promises":[{"t":138,"quote":"I wish to reaffirm Madagascar's support and its full readiness to work in a genuine spirit of cooperation to ensure the success of all of our work throughout this session.","topic":"UNGA 81st session","kind":"promise"},{"t":1276,"quote":"Madagascar is preparing at the national level a framework for the effective implementation of this transformation within our means.","topic":"UN reform","kind":"promise"},{"t":1349,"quote":"Our goal is to hold free, transparent, and universally accepted elections before the end of 2027.","topic":"Madagascar elections","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":3,"topic":null,"text":"The assembly will now hear an address by his excellency Randallin Mana, president of the Foundation of the Republic of Madagascar. I request protocol to escort his excellency and invite him to address the President of the United Nations General heads of state and government, your Excellency, Secretary General of the United Nations, distinguished delegates, ladies and I am particularly proud and honored to this August assembly today on behalf of the Republic of Madagascar."},{"t":83,"topic":"UNGA 81st session","text":"at this 81st session of the United Nations General Assembly for the rest of my speech. Allow me to now speak to you in the Malagasi language, my mother tongue, in honor of my country and the Malagasi I would like first of all on behalf of the Malagasi people and in my own name to extend my sincere congratulations to Mr. Khalur Rakman on his election as president of the 81st general assembly as well as to the vice In this regard, I wish to reaffirm Madagascar's support and its full readiness to work in a genuine spirit of cooperation to ensure the success of all of our work throughout this session."},{"t":153,"topic":"Madagascar development","text":"Mr. President, excellencies, ladies and gentlemen, we must acknowledge that the challenges that we have faced for decades, namely food insecurity, armed conflict, or natural disasters are still with us. Thus for Madagascar, as for many other nations, the new emerging challenges must not overshadow the priorities that still require our attention. The theme of this 81st session calls upon us to assume our shared responsibility for our destiny and for that of future generations with clear placing collective action, the common good, and the welfare of humanity at the center of our responses to the profound shaping our world."},{"t":218,"topic":"UN reform","text":"In light of these intersecting transformations and challenges, the question of trust in our collective action arises with renewed Indeed, we must admit, taking into all the hopes and expectations that we, the peoples of the United Nations, have placed in our organization, that trust has gradually eroded over time. The most vulnerable populations affected repeatedly or continuously by health crisis, food insecurity and hunger. The impacts of climate change exacerbated by current geopolitical tensions sometimes come to feel a certain skepticism regarding our collective capacity within the United Nations system to respond to the scourges of our age."},{"t":282,"topic":"Madagascar climate","text":"Mr. President, excellencies, ladies and gentlemen, in this regard, the realities on the ground in my country speak for themselves. In southern Madagascar, mothers walk dozens of kilometers under scorching heat in search of water from the bed of a dried up river. In the east, every year, increasingly violent and destructive tropical cyclones devastate crops, infrastructure, and human lives. In other regions, floods engulf rice granaries affecting entire communities. These images illustrate the daily vulnerability of our people, our Malagasi population. Faced with these recurring humanitarian emergencies amplified by climate change, considerable investments are made reflecting the unwavering commitment of our development partners working every year towards the achievement of the sustainable development goals, the SDGs, whether that be fighting hunger, providing education, or providing access to basic services for vulnerable populations."},{"t":376,"topic":"Madagascar development","text":"And we hope to mobilize $1.5 billion over 5 years for the implementation of the United Nations Sustainable Development Cooperation Framework for the period 2024 2028. Yet beyond commitments and resources what matters to us is their tangible impact on the daily lives of our people. Faced with the challenges of a constantly changing world, the refoundation government that I lead places food sovereignty, health and education at the heart of its action. This priority commitment serves the entire population, particularly women and children, while providing our youth with a means to build their future with confidence and contribute to national development. With more than 55% of its population under the age of 25, enjoys a tremendous demographic Driven by a firm political determination to build a brighter future for this dynamic youth."},{"t":449,"topic":"Madagascar education","text":"We recognize the importance of an education system which is fully aligned with labor market realities, an essential condition for sustainable development. And we hope that cooperation in this area will move beyond a strictly quantitative approach measured only by the volume of infrastructure built or the number of students enrolled and instead adapt fully to economic realities on the ground. Our aim is to focus on future oriented sectors while redefining our indicators of success to prioritize the practical acquisition of skills and medium-term employment outcomes. Mr. President. Excellencies, ladies and Madagascar's foreign policy is guided above all by the imperatives of economic and social development for the well-being of its people."},{"t":512,"topic":"Madagascar neutrality","text":"Madagascar has chosen a policy of engagement in all We are open to all international partnerships capable of meeting the aspirations of our people and supporting the general policy of the state of the Madagascar's position of neutrality with regard to global conflicts is consistent with its diplomatic tradition and its desire to preserve constructive relations with all its partners. is not ideological but is based on international partnership that can meet the aspirations of our people in an open spirit without exclusivity in full respect for ational sovereignty."},{"t":578,"topic":"UN reform","text":"The achievement of our ambitions cannot be separated from the international context in which they are pursued. Excellencies, Mr. President, ladies and can we speak of development when international peace and security are being tested by multiplying crises around the world and persistent trust requires the United Nations to maintain and to restore peace. We must be concerned that the multilateral system is struggling to contain escalating tensions fueled by geopolitical rivalries. These crises now affecting different regions of the have consequences for our states. They directly impact our economies and the daily lives of our populations through disruptions in energy supply chains and difficulties in the delivery of essential goods."},{"t":655,"topic":"Madagascar neutrality","text":"These are all factors which further aggravate the vulnerabilities that we already face. Confronted with this reality, we must have the courage to recognize and to accept the limitations of the multilateral system in its current form and functioning. It is urgent to initiate concerted and lasting action to guarantee every people the right to pursue their development in dignity and in stability. Mr. President, excellencies, ladies and gentlemen, far from observing the world as a passive spectator, Madagascar positions itself as an actor fully aware of its strategic place and responsibilities. Our country remains a committed and operational partner in the service of peace, development and security. Maritime security in the Mosambique channel and the western Indian Ocean remains at the heart of the regional initiatives in which Madagascar act actively participates."},{"t":724,"topic":"Regional cooperation","text":"We are determined to strengthen regional and multilateral cooperation founded on respect for national sovereignty. whilst also welcoming partnerships that align with our priorities and serve as genuine drivers of development. We also want to be part of strengthened uh regional cooperation in order to guarantee the security of our maritime areas. This approach will make it possible to ensure the sustainability of our energy supply chains. Mr. President, excellencies, ladies and gentlemen, what form of United Nations cooperation should we establish to support the contemporary transformation of our world? How can we restore trust? Mr. President, ladies and gentlemen, we must look to the future with greater to ensure lasting and measurable impact over the medium and long term."},{"t":797,"topic":"UN reform","text":"And to do this, we must move on to a new stage, one of increased solidarity, that is more integrated and better Madagascar advocates for a multilateral that is not only capable of acting, but that is also capable of supporting member states in their efforts to break the cycles of poverty and insecurity. My country aspires to an international order founded on the primacy of international law and trusts in the virtues of dialogue and diplomatic action. Our commitment to multilateral cooperation remains unwavering. Multilateralism is a privileged forum where states unite in a shared enabling them to define common and appropriate solutions in the face of challenges such as epidemics and climate disasters or armed conflicts arising from contemporary geopolitical rivalries and latent multi-dimensional tensions."},{"t":876,"topic":"UN reform","text":"History and future generations will judge our organization according to a single criterion, namely our ability to fulfill our original mission. serving all peoples without exclusion or privilege and in full respect for the sovereignty of nations. It is imperative to restore to the United Nations fully its central role as a guardian of peace as a strengthened institution capable of restoring order and challen and addressing the challenges of our time. Excellencies, ladies and gentlemen, our challenge today is therefore to rethink our mechanisms of cooperation through greater synergy between UN agencies and governmental structures in order to optimize the effectiveness of our actions on the ground, but also to provide better visibility of tangible results achieved for the benefit of In this regard, the success of our agenda largely depends on strengthening governance and strengthening institutions priorities that are fully integrated into Madagascar's process of reoundation."},{"t":949,"topic":"UN reform","text":"We recognize also the absolute necessity of reforming the United Nations so that it may serve all peoples. And in this spirit, we would like to propose the following. First, more inclusive global governance. This must begin with a rebalancing of decision-making power first and foremost by restoring the general assembly's full political weight and central place in global governance. It remains indeed the only organ where every nation regardless of power enjoys an equal and sovereign We must also correct the historical imbalance affecting Africa's representation on the security council. cannot remain on the margins of decisions."},{"t":1013,"topic":"Africa","text":"We have 1.4 billion inhabitants, decisions concerning international peace and security. Africa should be granted permanent representation on the security council in accordance with the Ezelwini consensus and the cert declaration which expresses which express a common position grounded in justice equity and represent representativeness within the African Union. We must also strengthen coherence between programs implemented by the UN resident coordinator offices and national priorities. UN country teams on the ground must listen carefully and respond effectively to priorities defined by host governments, avoiding one-sizefits-all approaches. Secondly, we need a more accessible international financial architecture for effective development support."},{"t":1078,"topic":"financial reform","text":"We must not neglect the reform of the international financial architecture. This means we need to rebalance access to financing. Current aid and lending criteria often rely solely on GDP per capita, excluding many vulnerable countries. The United Nations should therefore take into account the multi-dimensional vulnerability index so that access to concessional financing reflects climate shocks and external debt burdens. It would also be wise to support durable debt relief. This means advocating a for a faster, more predictable and more inclusive sovereign debt restructuring mechanism that would allow vulnerable countries to invest in the sustainable development goals rather than servicing unsustainable interest payments."},{"t":1159,"topic":"Climate finance","text":"The procedures for accessing UN funds should also be drastically simplified in order to reduce dispersement delays. For a vulnerable state facing crisis, slowness undermines confidence in the effectiveness of multilateralism. greater effectiveness in responding to climate and humanitarian emergencies. The multilateral system we seek should guarantee the fulfillment of climate finance commitments. It should serve both as a catalyst and a to ensure that developed countries in the north uh honor their commitments on climate finance particularly for the most exposed nations. It's also important to link emergency assistance with long-term structural investments."},{"t":1223,"topic":"UN reform","text":"Mr. President, excellencies, ladies and gentlemen, by embracing this theme, we are undertaking a commitment, namely to not postpone the reforms that are essential for enabling our organization to act with the integrity required by the challenges of our age. Building upon the achievements of the United Nations over 81 years. Our predecessors were able to build an organization suited to their time. It is now our responsibility to refound it so that it can address the challenges of today and tomorrow. Let us pass on to future generations an organization that unites, protects, and acts. For its part, Madagascar is preparing at the national level a framework for the effective implementation of this transformation within our means."},{"t":1291,"topic":"Madagascar elections","text":"Indeed, the process of refoundation initiated following the mobilization of Malagasi youth just one year ago serves as the foundation for responsible governance supported by strong institutions devoted to the public interest and having restored citizens trust in the state. This represents a genuine patriotic awakening driven by the deep conviction that sustainable development requires every citizen to find a full and meaningful place within the nation. To give substance to this vision, we have launched a historic process of inclusive national dialogue, bringing together all the vital forces of the nation, young people, women, persons with disabilities, political parties, civil society, the armed forces, and the private sector. We have established a clear timetable. Our goal is to hold free, transparent, and universally accepted elections before the end of 2027."},{"t":1360,"topic":"Ceremony","text":"Mr. Resident excellencies. Ladies and this platform uh speaking here at this rostrm also gives me the opportunity to express our gratitude to all our partners for the trust uh and support that they have provided and for the fraternal support of the southern African uh development community SADC and the United Nations uh going with standing with us hand in hand since the beginning of the reoundation process. Long live international cooperation of solidarity. Long live the United Nations. I thank you for your kind attention. On behalf of the assembly, I wish to thank the president of the Reoundation of the Republic of Madagascar. The assembly"}],"compare":[{"topic":"UN & its reform","share":0.3886,"mean":0.2038,"rank":23,"others":170},{"topic":"Global Economy","share":0.0643,"mean":0.0143,"rank":23,"others":31},{"topic":"Regional Security","share":0.0577,"mean":0.0043,"rank":7,"others":12},{"topic":"Africa","share":0.051,"mean":0.0233,"rank":33,"others":36},{"topic":"Climate Change","share":0.0502,"mean":0.0428,"rank":71,"others":77}]};
